"""Record final C71 outcome, correct stale running status, preserve all limitations."""
import pathlib,json,hashlib,datetime
import numpy as np
ROOT=pathlib.Path(__file__).resolve().parents[1];OUT=ROOT/'outputs';DEST=OUT/'free_simulation_closure_20261023_v1'
def read(p):return json.loads(pathlib.Path(p).read_text(encoding='utf-8-sig'))
def sha(p):return hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()
def write(p,j):
 with pathlib.Path(p).open('x',encoding='utf-8') as f:json.dump(j,f,indent=2,allow_nan=False)
v=read(DEST/'VERIFICATION71.json');assert v['status']=='C71_FULL_DEVELOPMENT_ASSESSMENT_INDEPENDENTLY_VERIFIED'
j=read(OUT/'FREE_SIMULATION_ASSESSMENT71_V1.json');assert sha(OUT/'FREE_SIMULATION_ASSESSMENT71_V1.json')==v['assessment_sha256']
acq=read(OUT/'ACQUISITION71_V1.json');source_checks=[]
for row in acq['sources']:
 assert sha(row['server_path'])==row['sha256'];source_checks.append(dict(path=row['server_path'],sha256=row['sha256']))
attr=[]
for fit in j['fits']:
 a=next(x for x in fit['arms'] if x['arm']=='native_search1000');b=next(x for x in fit['arms'] if x['arm']=='privileged_true_assignments')
 with np.load(a['arrays']['path'],allow_pickle=False) as z:p=z['predictions'];g=z['assignments']
 with np.load(b['arrays']['path'],allow_pickle=False) as z:q=z['predictions'];gq=z['assignments']
 data=pathlib.Path(acq['data_root']);truth=np.load(data/'state_springs5_test.npy',mmap_mode='r',allow_pickle=False)[:256,49:].copy()
 ep=np.mean((p.astype(np.float64)-truth)**2,axis=(1,2,3));eq=np.mean((q.astype(np.float64)-truth)**2,axis=(1,2,3));same=np.all(g==gq,axis=1);delta=ep-eq
 attr.append(dict(seed=fit['seed'],same_graph_trajectories=int(same.sum()),different_graph_trajectories=int((~same).sum()),same_graph_fraction=float(same.mean()),same_graph_prediction_max_abs_error=float(abs(p[same]-q[same]).max()) if same.any() else None,mean_extra_mse=float(delta.mean()),same_graph_contribution_to_mean=float(delta[same].sum()/256),different_graph_contribution_to_mean=float(delta[~same].sum()/256),different_graph_share_of_total_extra_error=float(delta[~same].sum()/delta.sum()) if delta.sum()!=0 else None))
write(DEST/'GRAPH_ATTRIBUTION71.json',dict(status='SAME_LIBRARY_GRAPH_ASSIGNMENT_DIAGNOSTIC',rows=attr,future_labels_used_only_for_scoring=True,privileged_graphs_not_ordinary_baseline=True,new_method=False))
write(DEST/'SOURCE_CHAIN71.json',dict(status='OFFICIAL_SOURCE_FILES_CURRENTLY_REHASHED',files=source_checks,revision=acq['revision']))
native=next(x for x in v['summary'] if x['arm']=='native_search1000');short=next(x for x in v['summary'] if x['arm']=='native_search100');oracle=next(x for x in v['summary'] if x['arm']=='privileged_true_assignments');var2=next(x for x in v['summary'] if x['arm']=='history_VAR2')
lines=['# C71正式开发评估已闭合：推断预算解释大幅差距，普通辨识仍更强','','终态：评估退出码0，时间'+v['terminal_receipt']['utc']+'。三颗原预算训练seed的12个神经评估臂全部完成，另有3个经典控制。先前启动guard错误、恢复记录和旧进度文件全部保留；不得再把C71写作训练中或评估运行中。','','## 任务和信息','','每条开发轨迹提供相同49步完整20维观测，随后自由预测50步，不喂回真实未来。开发样本为原source test的前256条；reserved EVAL的256:512行没有用于模型、选模或指标。普通神经臂不接收真实图；特权图臂只用于归因，图标签全局置换方向仅在TRAIN前128条确定。','模型库与proposal已分别完成96000次总更新，三颗seed各32000/32000。评估阶段0更新，沿用native reset-block VAL选择的checkpoint，未重训或重选。history-VAR使用同一49步历史逐轨迹拟合；其normalization和alpha只在2048条TRAIN校准。双方函数类、参数量和训练信息不同，不宣称完美计算/容量匹配。','','## H50前缀MSE','','| Arm | 三训练seed平均 / 固定控制 | 最小 | 最大 | 图准确率均值 |','| --- | ---: | ---: | ---: | ---: |']
for x in v['summary']:
 ga=f"{x['graph_accuracy_mean']:.6f}" if 'graph_accuracy_mean' in x else '—';label=x['arm']+('（特权归因）' if x['privileged'] else '')
 lines.append(f"| {label} | {x['h50_mse_mean']:.9f} | {x['h50_mse_min']:.9f} | {x['h50_mse_max']:.9f} | {ga} |")
lines+=['','经典控制各只有一次确定性评估，不把相同控制复制成三个独立seed。所有256条轨迹均有限值，没有裁剪或剔除。H1/10/25/50的逐seed前缀MSE/MAE、终点MSE及分坐标误差全部保存。','','## 能直接支持的判断','',f"1000步相对100步图搜索将平均H50 MSE降低{(1-native['h50_mse_mean']/short['h50_mse_mean'])*100:.2f}%，图准确率由{short['graph_accuracy_mean']:.4f}升至{native['graph_accuracy_mean']:.4f}。24组seed/batch的接受计数前100步均与1000步轨迹前缀一致，支持确实从相同已冻结起点比较搜索预算。这里未重跑神经搜索，复核的是原执行trace和保存预测。",f"真实图诊断进一步降低误差，但三颗seed的特权图平均MSE都仍高于history-VAR2。当前普通充分观测子集不支持必须新增世界模型机制；也不证明所有非线性、部分观测或结构泛化任务已被VAR解决。",'', '## 图推断与剩余库误差的分开诊断','','| Seed | 与特权图一致的轨迹数 | 不一致轨迹数 | 一致图预测最大差 | 不一致图贡献的平均额外MSE |','| --- | ---: | ---: | ---: | ---: |']
for x in attr:lines.append(f"| {x['seed']} | {x['same_graph_trajectories']} | {x['different_graph_trajectories']} | {x['same_graph_prediction_max_abs_error']:.3g} | {x['different_graph_contribution_to_mean']:.9f} |")
lines+=['','这些分组使用真实图作事后归因，不把真实图提供给普通臂，也不是一个新推断方法。真实图下仍有误差，不能把所有自由模拟残差都归为图推断；它也未独立识别训练不足、学习库近似和rollout性质各自的贡献。','native reset-block验证损失与这里50步无重置预测的指标定义不同，不能把它们的数量级差直接称为同一指标的复现失败。实际wall time受并发与硬件负载影响，只作执行记录，不构成公平速度排名。','','## 独立核验','','全部15个预测数组与3个选定checkpoint重新核对SHA；以13条轨迹分块独立重算保存预测的指标，最大绝对差'+f"{v['max_scalar_error']:.3g}"+'。两种history-VAR在全部256条历史上以增广最小二乘独立重放，最大预测差分别为'+f"{v['independent_classical_replay'][0]['prediction_max_abs_error']:.3g}"+'和'+f"{v['independent_classical_replay'][1]['prediction_max_abs_error']:.3g}"+'，通过原先数值资格阈值。官方source、协议、校准、选模和训练终态链均复核。','','## 研究决定','','C71历史执行承诺完成，停止在这个spring子集追加训练、图搜索步数或新架构。它是source-based子集的开发归因，不是完整原论文复现、未见结构组合或通用world-model验证。它不增加三篇主baseline之外的第四篇SOTA。','当前总体研究目标仍ACTIVE/UNACHIEVED，接受最终新颖方向0。后续问题必须具有独立机制和明确现有方法边界；不得把此处的普通推断预算控制、历史VAR或真实图诊断重新命名为创新。','','[完整机器复核](VERIFICATION71.json) · [逐seed与horizon CSV](METRICS71.csv) · [图归因](GRAPH_ATTRIBUTION71.json) · [原冻结协议](../../FREE_SIMULATION_PROTOCOL71_V1.md)','']
reports={'experimental_results.md':'\n'.join(lines),
'baseline_registry.md':'# Baseline scope\n\nC71 is the existing source-based Modular NRI spring subset, not a fourth primary SOTA. Three2000epoch fits, native validation-selected checkpoints,9 ordinary neural evaluations,3 privileged graph diagnostics and3 classical controls are closed. All ordinary forecasts use49 observed steps and freely simulate50. The classical calibration uses TRAIN only; neural models additionally learned from2048 TRAIN trajectories. Reserved EVAL remains closed.\n',
'literature_review.md':'# Existing-method boundary\n\nThe baseline is the pinned existing Modular NRI source recorded in VERIFICATION71.json. Longer native graph search and true-graph diagnostics are attribution controls; ordinary history-fitted VAR is system identification. No new literature-derived architecture or novelty claim is introduced by this closure. Main research papers remain WorldTS, LatentTSF and TSWM.\n',
'negative_evidence.md':'# Negative evidence\n\nOrdinary history-VAR2 has lower H50 mean error than every native seed and every privileged graph diagnostic. Larger native search budgets markedly improve results, contradicting attribution of the initial deficit solely to state representation or an inherently missing transition mechanism. The task is fully observed and favorable to ordinary identification. No independent structural-composition claim is supported. Startup guard errors were implementation incidents and were not counted as model failures.\n',
'hypothesis_space.md':'# Attribution\n\nGraph inference contributes to the native deficit: frozen1000-step search improves on100-step search, and privileged assignments reduce it further. Native library/free-rollout error remains with true assignments. Existing history-based controls are adequate on this subset, so the necessity of a new mechanism is not supported. Training convergence, library approximation and generalization beyond this source subset remain distinct and unproven explanations.\n',
'research_ideas.md':'# Candidate status\n\nNo final new direction follows from this result. Do not turn better graph search, known graph labels, or ordinary VAR into a new world-model framework. A genuinely different mechanism-composition or partially observed task would require its own prior-art check and competent controls; this existing fully observed subset is not evidence of that gap.\n',
'final_research_direction.md':'# Final C71 decision\n\nC71 development assessment is complete and independently verified. Stop this subset as a new-architecture route. All training and evaluation commitments under the frozen protocol are closed, with reserved EVAL unopened. The overall autonomous time-series world-model research goal remains active/unachieved, accepted final novel directions0. Return to the three primary papers and require a distinct, observable failure beyond ordinary controls and known prior art.\n'}
for name,tx in reports.items():
 with (DEST/name).open('x',encoding='utf-8') as f:f.write(tx)
write(DEST/'MANIFEST71.json',dict(utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),status='C71_EXECUTION_COMMITMENT_AND_ASSESSMENT_CLOSED',files={p.name:sha(p) for p in DEST.iterdir() if p.is_file()},new_method=False,accepted_final_directions=0,full_research_goal_achieved=False))
print(json.dumps(dict(status='C71_EXECUTION_COMMITMENT_AND_ASSESSMENT_CLOSED',graph_attribution=attr,accepted_final_directions=0)),flush=True)
